{
  "a_sentences": [
    {
      "a_text": "P1 Streitig ist eine Rückforderung von Fr. 375'042.- für von der Versicherten im Zeitraum vom 1. Mai 2018 bis 28. Februar 2020 über die OKP abgerechnete Labordienstleistungen.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Mit der Beschwerde in öffentlich-rechtlichen Angelegenheiten kann eine Rechtsverletzung nach Art. 95 f. BGG gerügt werden.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 Die Anwendung von kantonalem Gesetzesrecht überprüft das Bundesgericht nur auf Verletzung des Willkürverbots und anderer verfassungsmässiger Rechte.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Art. 25 ATSG ist in Verfahren vor dem kantonalen Schiedsgericht (Art. 89 KVG) grundsätzlich analog auf die Rückerstattung von Leistungen an nicht zugelassene Leistungserbringer anwendbar.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Die relative Verwirkungsfrist nach Art. 25 Abs. 2 ATSG läuft nicht, solange Leistungen nicht konkret ausbezahlt wurden.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Die Versicherte bestreitet nicht, dass die Streitigkeit in die Zuständigkeit des kantonalen Schiedsgerichts fällt.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Die Versicherte verfügt am streitgegenständlichen Standort über keine Bewilligung zur selbständigen Berufsausübung der Laborleitung in den Fachbereichen klinische Chemie, Hämatologie und medizinische Mikrobiologie und damit über keine Abrechnungsberechtigung zu Lasten der OKP.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Die Vorinstanz hat kein Recht verletzt, indem sie die einjährige relative Verwirkungsfrist als eingehalten erachtete, da die Frist erst nach den im Juni 2019 begonnenen Abklärungen zu laufen begann und die Klage vom 26. März 2020 fristgerecht erfolgte.",
      "b_propositions": ["P8"]
    }
  ]
}
